// Замер однотонных полей картинки через canvas (#494e0b — обрезка полей картинки карточки, card3).
// Картинка читается в странице: fetch(url) → createImageBitmap → canvas → средняя яркость и разброс по строкам/столбцам.
// Чтение только GET (storage supabase), ничего не пишет. Используется в card-trim-*.spec.ts и в галерее (gallery-poster-no-black).
import { Page } from '@playwright/test';

/** Строка «чёрная» — средняя яркость < 12, «белая» — > 243 (замер QA 2026-11-19). */
export const DARK = 12;
export const LIGHT = 243;
/** Линия «однотонная»: стандартное отклонение яркости ≤ UNIFORM_STD и цвет ≈ цвету крайней линии (±UNIFORM_DIFF). */
export const UNIFORM_STD = 6;
export const UNIFORM_DIFF = 10;

export type Lines = {
  w: number;
  h: number;
  /** Средняя яркость строки (сверху вниз) / столбца (слева направо). */
  rowMean: number[];
  colMean: number[];
  rowStd: number[];
  colStd: number[];
};

export type Region = { sx: number; sy: number; sw: number; sh: number };

/**
 * Загрузить картинку в странице и посчитать яркость по строкам и столбцам.
 * `region` — вырезать часть исходника (в пикселях оригинала) и нарисовать её в canvas (для видимой области cover).
 * Большие картинки уменьшаются до maxSide по длинной стороне (полосы при усреднении не теряются).
 */
export async function measureLines(page: Page, url: string, region?: Region, maxSide = 800): Promise<Lines> {
  return page.evaluate(
    async ({ url, region, maxSide }) => {
      const res = await fetch(url, { mode: 'cors', cache: 'force-cache' });
      if (!res.ok) throw new Error(`fetch ${url} → ${res.status}`);
      const bmp = await createImageBitmap(await res.blob());
      const r = region || { sx: 0, sy: 0, sw: bmp.width, sh: bmp.height };
      const k = Math.min(1, maxSide / Math.max(r.sw, r.sh));
      const w = Math.max(1, Math.round(r.sw * k));
      const h = Math.max(1, Math.round(r.sh * k));
      const c = document.createElement('canvas');
      c.width = w;
      c.height = h;
      const ctx = c.getContext('2d', { willReadFrequently: true })!;
      ctx.drawImage(bmp, r.sx, r.sy, r.sw, r.sh, 0, 0, w, h);
      const d = ctx.getImageData(0, 0, w, h).data;
      const L = new Float32Array(w * h);
      for (let i = 0; i < w * h; i++) L[i] = 0.299 * d[i * 4] + 0.587 * d[i * 4 + 1] + 0.114 * d[i * 4 + 2];
      const stats = (n: number, m: number, at: (a: number, b: number) => number) => {
        const mean: number[] = [];
        const std: number[] = [];
        for (let a = 0; a < n; a++) {
          let s = 0, s2 = 0;
          for (let b = 0; b < m; b++) { const v = at(a, b); s += v; s2 += v * v; }
          const mu = s / m;
          mean.push(Math.round(mu * 10) / 10);
          std.push(Math.round(Math.sqrt(Math.max(0, s2 / m - mu * mu)) * 10) / 10);
        }
        return { mean, std };
      };
      const rows = stats(h, w, (y, x) => L[y * w + x]);
      const cols = stats(w, h, (x, y) => L[y * w + x]);
      return {
        w: bmp.width, // исходный размер (до уменьшения) — для отчёта
        h: bmp.height,
        rowMean: rows.mean,
        colMean: cols.mean,
        rowStd: rows.std,
        colStd: cols.std,
        _scaled: [w, h],
      } as any;
    },
    { url, region: region ?? null, maxSide },
  );
}

/** Сколько подряд линий от края подходит под условие (edge: 'start' — сверху/слева, 'end' — снизу/справа). */
export function runFromEdge(n: number, edge: 'start' | 'end', ok: (i: number) => boolean) {
  let k = 0;
  for (let j = 0; j < n; j++) {
    const i = edge === 'start' ? j : n - 1 - j;
    if (!ok(i)) break;
    k++;
  }
  return k;
}

/** Тёмные строки (средняя < DARK) сверху/снизу, тёмные столбцы слева/справа — в линиях замера. */
export function darkEdges(l: Lines) {
  const dark = (arr: number[]) => (i: number) => arr[i] < DARK;
  return {
    top: runFromEdge(l.rowMean.length, 'start', dark(l.rowMean)),
    bottom: runFromEdge(l.rowMean.length, 'end', dark(l.rowMean)),
    left: runFromEdge(l.colMean.length, 'start', dark(l.colMean)),
    right: runFromEdge(l.colMean.length, 'end', dark(l.colMean)),
  };
}

/** Всего тёмных строк в замере (не только у края) — для «в видимой области нет чёрных строк». */
export const darkRowCount = (l: Lines) => l.rowMean.filter((v) => v < DARK).length;

/**
 * Однотонные поля по краям (доля от высоты/ширины замера): подряд от края линии с малым разбросом (std ≤ UNIFORM_STD)
 * и цветом, близким к крайней линии (±UNIFORM_DIFF).
 */
export function uniformMargins(l: Lines) {
  const side = (mean: number[], std: number[], edge: 'start' | 'end') => {
    const n = mean.length;
    const ref = mean[edge === 'start' ? 0 : n - 1];
    return runFromEdge(n, edge, (i) => std[i] <= UNIFORM_STD && Math.abs(mean[i] - ref) <= UNIFORM_DIFF);
  };
  const H = l.rowMean.length;
  const W = l.colMean.length;
  const top = side(l.rowMean, l.rowStd, 'start');
  const bottom = side(l.rowMean, l.rowStd, 'end');
  const left = side(l.colMean, l.colStd, 'start');
  const right = side(l.colMean, l.colStd, 'end');
  return {
    top, bottom, left, right,
    /** Доля полей по высоте (сверху + снизу) и по ширине (слева + справа). Вся картинка однотонная → 1. */
    vFrac: Math.min(1, (top + bottom) / H),
    hFrac: Math.min(1, (left + right) / W),
  };
}

export const COOKIE_PWA_INIT = () => {
  try {
    localStorage.setItem('b4s_install_prompt_dismissed_at', String(Date.now()));
    if (!localStorage.getItem('cookie-consent-v2')) {
      localStorage.setItem(
        'cookie-consent-v2',
        JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
      );
    }
  } catch {}
};

export const short = (src: string) => src.split('/').pop()?.split('?')[0] || src;
